for line in records:
    if line.display_type:
        continue
    poids = round((line.x_studio_vol or 0.0) * (line.x_studio_poids_au_m3 or 0.0), 2)
    if abs((line.x_studio_poids or 0.0) - poids) > 0.005:
        line.write({'x_studio_poids': poids})
